import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import app from 'flarum/forum/app';
import CreateTicketModal from './CreateTicketModal';
import TicketList from './TicketList';
export default class SupportPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.loading = true;
    app.store.find('tickets', {
      sort: '-createdAt',
      include: 'category,assignee,user'
    }).then(() => {
      this.loading = false;
      m.redraw();
    }).catch(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    return m(PageStructure, {
      className: "SupportPage",
      hero: () => m("h2", null, app.translator.trans('cengizkemec-support.forum.title'))
    }, m("div", {
      className: "SupportPage-toolbar"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => app.modal.show(CreateTicketModal)
    }, app.translator.trans('cengizkemec-support.forum.new_ticket'))), this.loading ? m(LoadingIndicator, null) : m(TicketList, null));
  }
}
flarum.reg.add('cengizkemec-support-tickets', 'forum/components/SupportPage', SupportPage);